/* =============================== APPROVAL CENTER =============================== */
const APF = { q: '', domain: 'all', type: 'all', prio: 'all', status: 'open', date: 'all', assignee: 'all' };
const APV = window.APV = { sel: null, refreshList() { const el = document.getElementById('apq'); if (el) el.innerHTML = apListHTML(); const c = document.getElementById('apcount'); if (c) c.textContent = apFiltered().length; } };
function apFiltered() { const n = nowTs(); return APPROVALS.filter(a => (APF.domain === 'all' || a.domain === APF.domain) && (APF.type === 'all' || a.type === APF.type) && (APF.prio === 'all' || a.priority === APF.prio) && (APF.status === 'all' || (APF.status === 'open' ? ['waiting', 'in_progress'].includes(a.status) : a.status === APF.status)) && (APF.assignee === 'all' || (APF.assignee === 'none' ? !a.assignee : a.assignee === APF.assignee)) && (APF.date === 'all' || n - a.ts < { d1: D, d7: 7 * D, d30: 30 * D }[APF.date]) && (!APF.q || (a.title + a.id + a.requester).toLowerCase().includes(APF.q.toLowerCase()))); }
