function licChips(tr) { return `<div class="lic">${tr.lic.map(l => `<span class="chip ${l.status === 'verified' ? 'v' : ['expired', 'rejected'].includes(l.status) ? 'x' : 'p'}" title="${esc(l.type + ' · ' + L3(STATUS[l.status].slice(2)))}">${l.type}${l.status === 'verified' ? ' ✓' : l.status === 'expiring' ? ' ⏱' : ['expired', 'rejected'].includes(l.status) ? ' ✕' : ' …'}</span>`).join('')}</div>`; }
function branchCell(tr) { const r = tr.branch.used / tr.branch.quota; return `<div style="min-width:96px"><div class="tnum" style="font-size:12.5px;margin-bottom:4px"><b>${tr.branch.used}</b> / ${tr.branch.quota}${tr.sub.addonBranch ? ` <span class="muted" style="font-size:11px" title="add-on">+${tr.sub.addonBranch}</span>` : ''}</div><div class="meter ${r >= 1 ? 'warn' : ''}"><i style="width:${r * 100}%"></i></div></div>`; }
